-- Accepted D1–D10. UUIDs are generated by JPA, not database defaults.
-- Name trim checks mirror Java 21 String.strip whitespace, preserving Unicode/case.
CREATE TABLE customers (
    id uuid CONSTRAINT pk_customers PRIMARY KEY,
    name text NOT NULL,
    email text NOT NULL,
    active boolean NOT NULL,
    CONSTRAINT ck_customers_name CHECK (char_length(name) BETWEEN 1 AND 200 AND name = btrim(name, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\1680\2000\2001\2002\2003\2004\2005\2006\2008\2009\200A\2028\2029\205F\3000')),
    CONSTRAINT ck_customers_email CHECK (
        char_length(email) BETWEEN 1 AND 254 AND email = lower(email)
        AND email = btrim(email, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\1680\2000\2001\2002\2003\2004\2005\2006\2008\2009\200A\2028\2029\205F\3000'))
);
CREATE UNIQUE INDEX uq_customers_email ON customers (lower(email));

CREATE TABLE products (
    id uuid CONSTRAINT pk_products PRIMARY KEY,
    name text NOT NULL,
    price numeric NOT NULL,
    active boolean NOT NULL,
    CONSTRAINT ck_products_name CHECK (char_length(name) BETWEEN 1 AND 200 AND name = btrim(name, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\1680\2000\2001\2002\2003\2004\2005\2006\2008\2009\200A\2028\2029\205F\3000')),
    CONSTRAINT ck_products_price CHECK (price NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND scale(price) <= 2 AND price >= 0 AND price <= 999999.99)
);

CREATE TABLE orders (
    id uuid CONSTRAINT pk_orders PRIMARY KEY,
    customer_id uuid NOT NULL,
    subtotal numeric NOT NULL,
    discount numeric NOT NULL,
    total numeric NOT NULL,
    CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE NO ACTION,
    CONSTRAINT ck_orders_subtotal CHECK (subtotal NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND scale(subtotal) <= 2 AND subtotal >= 0),
    CONSTRAINT ck_orders_discount CHECK (discount NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND scale(discount) <= 2 AND discount >= 0),
    CONSTRAINT ck_orders_total CHECK (total NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND scale(total) <= 2 AND total >= 0)
);
CREATE INDEX ix_orders_customer ON orders(customer_id);

CREATE TABLE order_items (
    id uuid CONSTRAINT pk_order_items PRIMARY KEY,
    order_id uuid NOT NULL,
    product_id uuid NOT NULL,
    product_name text NOT NULL,
    quantity integer NOT NULL,
    unit_price numeric NOT NULL,
    line_total numeric NOT NULL,
    CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE NO ACTION,
    CONSTRAINT fk_order_items_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE NO ACTION,
    CONSTRAINT uq_order_items_product UNIQUE (order_id, product_id),
    CONSTRAINT ck_order_items_name CHECK (char_length(product_name) BETWEEN 1 AND 200 AND product_name = btrim(product_name, U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\1680\2000\2001\2002\2003\2004\2005\2006\2008\2009\200A\2028\2029\205F\3000')),
    CONSTRAINT ck_order_items_quantity CHECK (quantity BETWEEN 1 AND 10000),
    CONSTRAINT ck_order_items_unit_price CHECK (unit_price NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND scale(unit_price) <= 2 AND unit_price >= 0 AND unit_price <= 999999.99),
    CONSTRAINT ck_order_items_line_total CHECK (line_total NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND scale(line_total) <= 2 AND line_total >= 0)
);
CREATE INDEX ix_order_items_product ON order_items(product_id);
